  /* ---------- 三次贝塞尔缓动（官方 ease:[x1,y1,x2,y2]） ---------- */
  function bezierEase(x1, y1, x2, y2) {
    const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
    const cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
    const sx = t => ((ax * t + bx) * t + cx) * t, dx = t => (3 * ax * t + 2 * bx) * t + cx;
    const sy = t => ((ay * t + by) * t + cy) * t;
    return u => {
      u = Math.max(0, Math.min(1, u));
      let t = u;
      for (let i = 0; i < 6; i++) { const x = sx(t) - u; if (Math.abs(x) < 1e-5) break;
        const d = dx(t); if (Math.abs(d) < 1e-6) break; t -= x / d; }
      return sy(Math.max(0, Math.min(1, t)));
    };
  }
  const lerp = (a, b, e) => a + (b - a) * e;
  const interpArr = (a, b, e) => a.map((v, i) => lerp(v, b[i], e));
  function sample(keys, t, interp) {
    if (!keys || !keys.length) return null;
    if (t <= keys[0].t) return interp ? interp(keys[0].v, keys[0].v, 0) : keys[0].v;
    const last = keys[keys.length - 1];
    if (t >= last.t) return interp ? interp(last.v, last.v, 0) : last.v;
    let i = 0; while (i < keys.length - 1 && keys[i + 1].t < t) i++;
    const a = keys[i], b = keys[i + 1];
    const u = (t - a.t) / Math.max(1e-6, b.t - a.t);
    const e = bezierEase(...a.ease)(u);
    return interp ? interp(a.v, b.v, e) : (e < 1 ? a.v : b.v);
  }

  function expressionAt(keys, time) {
    let name = 'neutral', blink = 0;
    for (const key of keys || []) {
      if (key.t > time) break;
      if (key.v === 'blink') {
        const u = (time - key.t) / .18;
        if (u >= 0 && u < 1) blink = Math.sin(u * Math.PI) ** 2;
      } else name = key.v;
    }
    return { name, blink };
  }

