    let frame = null;
    try { frame = player.advance(dt); if (frame) draw(frame, dt); } catch (e) { /* 单帧绘制失败不终止动画 */ }
    if (typeof view.onFrame === 'function') { try { view.onFrame(player.state, frame && frame.name); } catch (e) {} }
